using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

Console.WriteLine("Research Agent Starting...");

// Configure the chat client with tool support
var innerClient = new OpenAI.OpenAIClient(
    Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "")
    .GetChatClient("gpt-4o-mini");

IChatClient chatClient = new ChatClientBuilder(innerClient.AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// Agent tools
var researchNotes = new ResearchNotes();
var webSearch = new WebSearchTool();

var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(webSearch.SearchWeb),
        AIFunctionFactory.Create(researchNotes.AddNote),
        AIFunctionFactory.Create(researchNotes.GetNotes),
    ]
};

// Get topic from user
Console.Write("\nEnter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// Run the research agent loop
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (make multiple searches with different queries)
        2. Taking notes on key findings using the note-taking tool
        3. After gathering enough information, retrieve your notes and provide a comprehensive summary

        Always search at least 2-3 different queries to get broad coverage, take notes on
        important findings, then summarize everything at the end.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await chatClient.GetResponseAsync(messages, chatOptions);
Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

// Display collected notes
var notes = researchNotes.GetAllNotes();
if (notes.Count > 0)
{
    Console.WriteLine("\n=== Research Notes ===\n");
    for (int i = 0; i < notes.Count; i++)
    {
        Console.WriteLine($"  {i + 1}. {notes[i]}");
    }
}

// --- Tool Implementations ---

/// <summary>Provides web search capability using a search API.</summary>
public class WebSearchTool
{
    private static readonly HttpClient _http = new();

    [Description("Search the web for information on a given query. Returns a list of search result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  [Searching: \"{query}\"]");

        try
        {
            // Use DuckDuckGo instant answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var result = await _http.GetFromJsonAsync<JsonElement>(url);

            var snippets = new List<string>();

            // Extract abstract
            var abstractText = result.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrEmpty(abstractText))
                snippets.Add($"Summary: {abstractText}");

            // Extract related topics
            if (result.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                        snippets.Add(text.GetString() ?? "");
                }
            }

            if (snippets.Count == 0)
                return $"No detailed results found for '{query}'. Try a different search query.";

            return string.Join("\n\n", snippets);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>Provides note-taking capability for the research agent.</summary>
public class ResearchNotes
{
    private readonly List<string> _notes = [];

    [Description("Add a research note to remember a key finding.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Note saved: \"{note[..Math.Min(note.Length, 60)]}...\"]");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public List<string> GetAllNotes() => [.. _notes];
}

